BEGIN TRY
    BEGIN TRANSACTION;

    -- Insert order header
    INSERT INTO Orders (CustomerID, OrderDate, TotalAmount)
    VALUES (@CustomerID, GETDATE(), 0);

    DECLARE @NewOrderID INT = SCOPE_IDENTITY();

    -- Insert order details and check stock
    INSERT INTO OrderDetails (OrderID, ProductID, Quantity, UnitPrice)
    SELECT @NewOrderID, ProductID, @Qty, UnitPrice
    FROM Products
    WHERE ProductID = @ProductID
      AND StockQuantity >= @Qty;

    IF @@ROWCOUNT = 0
    BEGIN
        THROW 50001, 'Insufficient stock for this product.', 1;
    END

    -- Update stock
    UPDATE Products
    SET StockQuantity = StockQuantity - @Qty
    WHERE ProductID = @ProductID;

    COMMIT TRANSACTION;
    PRINT 'Order placed successfully.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
